node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const info = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\n' + t.name + ':', info.map(c => c.name + ' (' + c.type + ')').join(', '));
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get order details
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-5B048F'\").get();
console.log('=== ORDER ===');
console.log(JSON.stringify(order, null, 2));

// Get order items
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-5B048F'\").all();
console.log('\n=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get order payments
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-5B048F'\").all();
console.log('\n=== PAYMENTS ===');
console.log(JSON.stringify(payments, null, 2));

// Get fulfillments
const fulfillments = db.prepare(\"SELECT * FROM order_fulfillments WHERE order_id = 'ORD-5B048F'\").all();
console.log('\n=== FULFILLMENTS ===');
console.log(JSON.stringify(fulfillments, null, 2));
"

